-- Nexmark q18 on flink, UPSERT-SINK sink variant. Latest bid per
-- bidder/auction pair: deduplication by ROW_NUMBER = 1 over a descending time
-- order. Unbounded keyspace, one retained row per key. The ORDER BY is made
-- TOTAL for the same reason as q5 and q19: two bids by one bidder on one
-- auction in the same millisecond have no defined 'latest', and each engine
-- would retain an arbitrary one. price then url break the tie - together with
-- the partition key and datetime they identify a bid in this dataset.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q18up-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q18 (`auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT, PRIMARY KEY (`bidder`, `auction`) NOT ENFORCED) WITH (
  'connector' = 'upsert-kafka',
  'topic' = '__OUT__',
  'properties.bootstrap.servers' = 'kafka:29092',
  'key.format' = 'json',
  'value.format' = 'json'
);
INSERT INTO sink_q18
SELECT auction, bidder, price, channel, url, `datetime` FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY bidder, auction ORDER BY `datetime` DESC, price DESC, url DESC) AS rn FROM bid) AS R WHERE rn = 1;
